begin;
create table public.services(id text primary key,title text not null,price_fils integer not null check(price_fils>0),active boolean not null default true);
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null check(char_length(display_name)<=120));
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),service_id text not null references public.services(id),price_fils integer not null check(price_fils>0),status text not null default 'pending' check(status in ('pending','paid','fulfilled','cancelled')),details jsonb not null default '{}' check(jsonb_typeof(details)='object' and octet_length(details::text)<=16000),created_at timestamptz not null default now());
create index orders_user_idx on public.orders(user_id);
alter table public.services enable row level security;
alter table public.profiles enable row level security;
alter table public.orders enable row level security;
revoke all on public.services,public.profiles,public.orders from anon,authenticated;
grant select on public.services to anon,authenticated;
grant select,insert,update on public.profiles to authenticated;
grant select on public.orders to authenticated;
grant insert(service_id,details,price_fils) on public.orders to authenticated;
create policy catalog_read on public.services for select to anon,authenticated using(active);
create policy profile_read on public.profiles for select to authenticated using(user_id=(select auth.uid()));
create policy profile_insert on public.profiles for insert to authenticated with check(user_id=(select auth.uid()));
create policy profile_update on public.profiles for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy order_read on public.orders for select to authenticated using(user_id=(select auth.uid()));
create policy order_insert on public.orders for insert to authenticated with check(user_id=(select auth.uid()) and status='pending' and exists(select 1 from public.services s where s.id=service_id and s.active and s.price_fils=orders.price_fils));
insert into public.services(id,title,price_fils) values ('cv','سيرة ذاتية',2000),('wedding','دعوة زفاف',5000),('birthday','دعوة عيد ميلاد',2000),('card','بطاقة أعمال',3000),('qr','QR مخصص',1000),('links','صفحة روابط شخصية',2000),('catalog','كتالوج إلكتروني',5000),('menu','منيو إلكتروني',5000),('website','موقع شخصي',10000),('certificate','شهادة إلكترونية',1000);
commit;